+function parseVersion(v: string): Version {
+  const parts = v.split(".");
+  if (parts.length !== 3) throw new Error(`Invalid version: ${v}`);
+  const nums = parts.map((s) => {
+    if (!/^\d+$/.test(s)) throw new Error(`Invalid version: ${v}`);
+    return parseInt(s, 10);
+  });
+  return nums as Version;
